import fs from 'node:fs';
import * as alphaTab from '@coderline/alphatab';
const oracle = JSON.parse(fs.readFileSync('oracle.json', 'utf8'));
const settings = new alphaTab.Settings();
Object.assign(settings.importer, oracle.importerSettings);
alphaTab.Logger.logLevel = alphaTab.LogLevel.None;
const score = alphaTab.importer.ScoreLoader.loadScoreFromBytes(
  new Uint8Array(fs.readFileSync(process.argv[2])), settings);
console.log(JSON.stringify({
  metadata: {
    music: score.music, tab: score.tab,
    instructions: score.instructions, notices: score.notices
  },
  tracks: score.tracks.map(track => ({
    playback: {
      port: track.playbackInfo.port,
      primaryChannel: track.playbackInfo.primaryChannel,
      secondaryChannel: track.playbackInfo.secondaryChannel,
      mute: track.playbackInfo.isMute, solo: track.playbackInfo.isSolo
    },
    staves: track.staves.map(staff => ({
      bars: staff.bars.map(bar => ({
        voices: bar.voices.map(voice => ({
          index: voice.index, isEmpty: voice.isEmpty,
          beats: voice.beats.map(beat => ({
            isEmpty: beat.isEmpty, isRest: beat.isRest,
            graceType: beat.graceType, text: beat.text,
            duration: beat.duration, dots: beat.dots,
            tupletNumerator: beat.tupletNumerator,
            tupletDenominator: beat.tupletDenominator,
            playbackStart: beat.playbackStart,
            playbackDuration: beat.playbackDuration,
            notes: beat.notes.map(note => ({
              string: note.string, fret: note.fret,
              durationPercent: note.durationPercent,
              isTieOrigin: note.isTieOrigin,
              isTieDestination: note.isTieDestination,
              isLetRing: note.isLetRing
            }))
          }))
        }))
      }))
    }))
  }))
}, null, 2));
